// base32: 4,000,000 generated bytes encoded as Base32 (RFC 4648, groups of
// 5 bytes as 8 letters of A-Z2-7) and decoded again. Prints the length of
// the text, a position-weighted checksum, and 1 when decoding gives the
// bytes back.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define N 4000000

int main(void) {
    static const char ABC[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
    uint8_t *data = malloc(N), *back = malloc(N);
    char *text = malloc(N / 5 * 8);
    for (int64_t i = 0; i < N; i++) data[i] = (uint8_t)((i * 2654435761) >> 13 & 255);
    for (int64_t g = 0; g < N / 5; g++) {
        uint64_t v = 0;
        for (int k = 0; k < 5; k++) v = v << 8 | data[5 * g + k];
        for (int k = 0; k < 8; k++) text[8 * g + k] = ABC[v >> (35 - 5 * k) & 31];
    }
    int64_t len = N / 5 * 8, check = 0;
    for (int64_t i = 0; i < len; i++) check += (int64_t)text[i] * (i % 251 + 1);
    for (int64_t g = 0; g < N / 5; g++) {
        uint64_t v = 0;
        for (int k = 0; k < 8; k++) {
            char c = text[8 * g + k];
            v = v << 5 | (uint64_t)(c >= 'A' ? c - 'A' : c - '2' + 26);
        }
        for (int k = 0; k < 5; k++) back[5 * g + k] = (uint8_t)(v >> (32 - 8 * k));
    }
    printf("%lld %lld %d\n", (long long)len, (long long)check, memcmp(back, data, N) == 0);
    return 0;
}
